(6, 'Dr. Richard Harris', 'PTSD & EMDR Therapy', 'richard.harris@example.com', 'A certified EMDR practitioner specializing in trauma resolution, post-traumatic growth, and treating chronic PTSD symptoms.', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&q=80&w=300', 15),
(7, 'Dr. Lisa Cooper', 'Somatic Experiencing practitioner', 'lisa.cooper@example.com', 'Combines body-oriented trauma recovery methods with traditional psychotherapy to resolve deep-seated stress and trauma patterns.', 'https://images.unsplash.com/photo-1614608682850-e0d6ed316d47?auto=format&fit=crop&q=80&w=300', 8),
